 'use strict';
-// Implement the public contract in TASK.md.
-module.exports = {};
+const fs = require('node:fs');
+const fsp = fs.promises;
+const path = require('node:path');
+const ID = /^[a-z][a-z0-9-]{0,31}$/;
+const STATUSES = new Set(['pending', 'running', 'completed', 'failed', 'blocked']);
+const clone = value => JSON.parse(JSON.stringify(value));
+function checkpoint(jobs) { return { version: 1, jobs: [...jobs.values()].sort((a,b) => a.id.localeCompare(b.id)).map(clone) }; }
+function validateStored(value, file) {
+  const bad = () => { throw new Error(`Corrupt checkpoint: ${file}`); };
+  if (!value || value.version !== 1 || !Array.isArray(value.jobs)) bad();
+  const ids = new Set();
+  for (const j of value.jobs) {
+    if (!j || typeof j.id !== 'string' || !ID.test(j.id) || ids.has(j.id) || !Array.isArray(j.dependsOn) ||
+      j.dependsOn.some(x => typeof x !== 'string') || new Set(j.dependsOn).size !== j.dependsOn.length ||
+      j.dependsOn.includes(j.id) || !STATUSES.has(j.status) || !Number.isInteger(j.attempt) || j.attempt < 0 ||
+      Object.keys(j).some(k => !['id','dependsOn','payload','status','attempt','result','error'].includes(k)) ||
+      (j.status === 'failed' && typeof j.error !== 'string') ||
+      (j.status === 'completed' && !Object.hasOwn(j, 'result'))) bad();
+    ids.add(j.id);
+  }
+  for (const j of value.jobs) for (const d of j.dependsOn) if (!ids.has(d)) bad();
+  const graph = new Map(value.jobs.map(j => [j.id, j.dependsOn]));
+  const visiting = new Set(), visited = new Set();
+  function visit(id) { if (visiting.has(id)) bad(); if (visited.has(id)) return; visiting.add(id); for (const d of graph.get(id)) visit(d); visiting.delete(id); visited.add(id); }
+  for (const id of graph.keys()) visit(id);
+}
+async function atomicWrite(file, data) {
+  await fsp.mkdir(path.dirname(file), {recursive:true});
+  const tmp = `${file}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+  try { await fsp.writeFile(tmp, JSON.stringify(data) + '\n'); await fsp.rename(tmp, file); }
+  catch (e) { try { await fsp.unlink(tmp); } catch {} throw e; }
+}
+function createScheduler({file, concurrency, execute, onStage} = {}) {
+  if (typeof file !== 'string' || !file) throw new TypeError('file must be a non-empty string');
+  if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 8) throw new TypeError('concurrency must be an integer from 1 to 8');
+  if (typeof execute !== 'function') throw new TypeError('execute must be a function');
+  if (onStage !== undefined && typeof onStage !== 'function') throw new TypeError('onStage must be a function');
+  let text;
+  try { text = fs.readFileSync(file, 'utf8'); } catch (e) { if (e.code !== 'ENOENT') throw e; }
+  const jobs = new Map();
+  if (text !== undefined) {
+    let value; try { value = JSON.parse(text); } catch { throw new Error(`Corrupt checkpoint: ${file}`); }
+    validateStored(value, file); for (const j of value.jobs) jobs.set(j.id, clone(j));
+    const recovered = [...jobs.values()].some(j => j.status === 'running');
+    for (const j of jobs.values()) if (j.status === 'running') j.status = 'pending';
+    if (recovered) { fs.mkdirSync(path.dirname(file), {recursive:true}); const tmp = `${file}.tmp-${process.pid}-${Date.now()}`; try { fs.writeFileSync(tmp, JSON.stringify(checkpoint(jobs))+'\n'); fs.renameSync(tmp,file); } catch(e) { try { fs.unlinkSync(tmp); } catch {} throw e; } }
+  }
+  let write = Promise.resolve();
+  const persist = () => { const data = checkpoint(jobs); write = write.then(() => atomicWrite(file, data)); return write; };
+  let draining;
+  function snapshot() { return clone(checkpoint(jobs)); }
+  async function enqueue(batch) {
+    if (!Array.isArray(batch)) throw new TypeError('jobs must be an array');
+    const proposed = new Map(jobs), ids = new Set();
+    for (const input of batch) {
+      if (!input || typeof input !== 'object' || Array.isArray(input) || Object.keys(input).some(k => !['id','dependsOn','payload'].includes(k))) throw new Error('invalid job');
+      const id = input.id, deps = input.dependsOn === undefined ? [] : input.dependsOn;
+      if (typeof id !== 'string' || !ID.test(id) || ids.has(id) || proposed.has(id)) throw new Error(`invalid or duplicate id: ${id}`);
+      if (!Array.isArray(deps) || deps.some(d => typeof d !== 'string') || new Set(deps).size !== deps.length || deps.includes(id)) throw new Error(`invalid dependencies for ${id}`);
+      ids.add(id); proposed.set(id, {id, dependsOn:[...deps], payload:input.payload === undefined ? null : clone(input.payload), status:'pending', attempt:0});
+    }
+    for (const j of proposed.values()) for (const d of j.dependsOn) if (!proposed.has(d)) throw new Error(`unknown dependency: ${d}`);
+    validateStored(checkpoint(proposed), file);
+    for (const [id,j] of proposed) if (!jobs.has(id)) jobs.set(id,j);
+    if (batch.length) await persist();
+    return snapshot();
+  }
+  async function executeOne(job) {
+    await onStage?.('claimed', job.id);
+    try {
+      const result = await execute({id:job.id, payload:clone(job.payload), attempt:job.attempt});
+      job.status='completed'; job.result=clone(result); delete job.error; await persist(); await onStage?.('completed', job.id);
+    } catch (e) {
+      if (job.status === 'running') { job.status='failed'; job.error=String(e); delete job.result; await persist(); }
+      // Execution failures are terminal job outcomes; the drain continues.
+    }
+  }
+  async function drain() {
+    const active = new Set();
+    for (;;) {
+      for (const j of [...jobs.values()].sort((a,b)=>a.id.localeCompare(b.id))) if (j.status === 'pending' && j.dependsOn.some(d => ['failed','blocked'].includes(jobs.get(d).status))) { j.status='blocked'; await persist(); }
+      const ready = [...jobs.values()].filter(j => j.status==='pending' && j.dependsOn.every(d=>jobs.get(d).status==='completed')).sort((a,b)=>a.id.localeCompare(b.id));
+      while (active.size < concurrency && ready.length) { const j=ready.shift(); j.status='running'; j.attempt++; await persist(); let task; task=executeOne(j).finally(()=>active.delete(task)); active.add(task); }
+      if (!active.size) { if (![...jobs.values()].some(j=>j.status==='pending' && j.dependsOn.every(d=>jobs.get(d).status==='completed'))) return snapshot(); }
+      else await Promise.race(active);
+    }
+  }
+  function run() { if (!draining) draining=drain().finally(()=>{draining=null;}); return draining; }
+  return {enqueue, run, snapshot};
+}
+module.exports = createScheduler;
+module.exports.createScheduler = createScheduler;
